use std::{env,fs,path::Path};
use wasmc::canonical_host_assets::{compile_canonical_host_assets,CanonicalAssetBuffers};
fn pins(v:&[Vec<u8>;4])->Vec<u8>{v.iter().flat_map(|b|wasmc::self_bundle::sha256(b)).collect()}
fn main(){let a:Vec<_>=env::args().collect();let base=Path::new(&a[1]);let f=base.join("examples/current/canonical-checked-results-v2");let kit=base.join("lib-releases/wasmc-json/0.0.7");let read=|p:&Path|fs::read(p).expect("input");let tuple=|name:&str|{let root=kit.join("host").join(name);["lib.wit","execution-abi.json","provider-contract.json","binding.json"].map(|n|read(&root.join(n)))};let entry=tuple("entry");let operations=tuple("operations");let ep=pins(&entry);let op=pins(&operations);let source=fs::read_to_string(f.join("ordinary.wasmc")).unwrap();let activation=read(&base.join("activation-canonical.json"));let core=read(&kit.join("root/artifact.wasm"));let wit=read(&kit.join("root/lib.wit"));let template=read(&f.join("canonical-template.json"));let frame=compile_canonical_host_assets(&source,CanonicalAssetBuffers{entry:[&entry[0],&entry[1],&entry[2],&entry[3],&ep],extension:[&activation,&core,&wit,&template,&operations[0],&operations[1],&operations[2],&operations[3],&op]}).expect("native frame");let expected=read(&base.join("frame-canonical-input.bin"));assert_eq!(frame,expected,"native frame differs from portable");fs::write(base.join("frame-native.bin"),&frame).unwrap();println!("native_and_portable_frame_equal=true bytes={} sha256={}",frame.len(),wasmc::self_bundle::hex(&wasmc::self_bundle::sha256(&frame)));}
